99	    private static final int MAX_OWNERS_PER_DAY = 100;
100	
101	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
102	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
103	
104	    /** Fixed public-holiday calendar: a registration date landing on any of these is rolled forward past it. */
105	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
106	        LocalDate.of(2026, 1, 1),
107	        LocalDate.of(2026, 1, 26),
108	        LocalDate.of(2026, 4, 25),
109	        LocalDate.of(2026, 12, 25),
110	        LocalDate.of(2026, 12, 28));
