115	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
116	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
117	
118	    /**
119	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
120	     * is listed here must carry exactly the required number of national digits, otherwise it is
121	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
122	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
123	     */
124	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
125	        "61", 9,
126	        "1", 10);
127	
