550	    /**
551	     * Generate the version-2 unified member id formatted {@code <REGION><FY><HASH8><CHK>}, where
552	     * {@code REGION} is the version-2 region code (the canonical region derived from the owner's
553	     * identity with the fixed {@code V2} version tag mixed in, see {@link #deriveRegionV2}),
554	     * {@code FY} is the two-digit fiscal year that the owner's business-day-adjusted registration
555	     * date falls in, {@code HASH8} is the first eight upper-case hex characters of the SHA-256 digest
556	     * of {@code normalizedTelephone + lastName}, and {@code CHK} is a single Luhn check digit computed
557	     * over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code V2NSW271A2B3C4D5}). Because the
558	     * version-2 region prefix carries the {@code V2} tag, the id can never equal a version-1 member id.
559	     *
560	     * @param owner the owner whose (already-normalized) telephone, last name, postcode, city and
561	     *              registration date are read
562	     * @return the generated (collision-free) member id
563	     */
564	    private String generateMemberId(Owner owner) {
565	        String region = deriveRegionV2(owner.getPostcode(), owner.getCity());
566	        String fy = String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100);
567	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
568	        String base = region + fy + hash8;
569	        String memberId = base + luhnCheckDigit(base);
570	        return deduplicateMemberId(memberId);
571	    }
572	
573	    /**
574	     * Return a member id that does not collide with any existing owner's member id. When the given
575	     * base id is already unique it is returned unchanged; otherwise {@code -<n>} is appended with the
576	     * smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW271A2B3C4D5}, then
577	     * {@code NSW271A2B3C4D5-2}, {@code NSW271A2B3C4D5-3}, ...). The incoming owner is not yet
578	     * persisted, so it never counts as a collision with itself.
579	     *
580	     * @param baseId the computed {@code <REGION><FY><HASH8><CHK>} member id
581	     * @return the de-duplicated member id
582	     */
583	    private String deduplicateMemberId(String baseId) {
584	        java.util.Set<String> existingIds = this.clinicService.findAllOwners().stream()
585	            .map(Owner::getMemberId)
586	            .filter(java.util.Objects::nonNull)
587	            .collect(java.util.stream.Collectors.toSet());
588	        if (!existingIds.contains(baseId)) {
589	            return baseId;
590	        }
591	        int n = 2;
592	        String candidate = baseId + "-" + n;
593	        while (existingIds.contains(candidate)) {
594	            n++;
595	            candidate = baseId + "-" + n;
596	        }
597	        return candidate;
598	    }
