600	    /**
601	     * Compute the single Luhn check digit (0-9) over the digits contained in the given value.
602	     * Non-digit characters are ignored. A {@code null} or digit-free value yields a check digit of 0.
603	     *
604	     * @param value the value whose digits the check digit is computed over
605	     * @return the Luhn check digit
606	     */
607	    private int luhnCheckDigit(String value) {
608	        if (value == null) {
609	            return 0;
610	        }
611	        int sum = 0;
612	        boolean doubleDigit = true;
613	        for (int i = value.length() - 1; i >= 0; i--) {
614	            char c = value.charAt(i);
615	            if (c < '0' || c > '9') {
616	                continue;
617	            }
618	            int digit = c - '0';
619	            if (doubleDigit) {
620	                digit *= 2;
621	                if (digit > 9) {
622	                    digit -= 9;
623	                }
624	            }
625	            sum += digit;
626	            doubleDigit = !doubleDigit;
627	        }
628	        return (10 - (sum % 10)) % 10;
629	    }
