631	    /**
632	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
633	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
634	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
635	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
636	     * known region.
637	     *
638	     * @param postcode the owner's postcode, may be {@code null}
639	     * @param city     the owner's city
640	     * @return the derived region code
641	     */
642	    private String deriveRegion(String postcode, String city) {
643	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
644	            int value = Integer.parseInt(postcode);
645	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
646	                int[] range = entry.getValue();
647	                if (value >= range[0] && value <= range[1]) {
648	                    return entry.getKey();
649	                }
650	            }
651	        }
652	        String region = CITY_REGION.get(city);
653	        return region != null ? region : "UNKNOWN";
654	    }
