672	    /**
673	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
674	     * bytes of {@code input}.
675	     *
676	     * @param input  the value to digest
677	     * @param length the number of leading hex characters to return
678	     * @return the truncated upper-case hex digest
679	     */
680	    private String shortSha256Hex(String input, int length) {
681	        try {
682	            byte[] digest = MessageDigest.getInstance("SHA-256")
683	                .digest(input.getBytes(StandardCharsets.UTF_8));
684	            StringBuilder sb = new StringBuilder(digest.length * 2);
685	            for (byte b : digest) {
686	                sb.append(String.format("%02x", b));
687	            }
688	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
689	        } catch (java.security.NoSuchAlgorithmException e) {
690	            throw new IllegalStateException("SHA-256 not available", e);
691	        }
692	    }
