694	    /**
695	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
696	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
697	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
698	     * date that is stored, returned and used for every value derived from it.
699	     *
700	     * @param date the effective registration date (supplied or defaulted)
701	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
702	     */
703	    private LocalDate rollToBusinessDay(LocalDate date) {
704	        while (!isBusinessDay(date)) {
705	            date = date.plusDays(1);
706	        }
707	        return date;
708	    }
