710	    /**
711	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
712	     *
713	     * @param date the date to test
714	     * @return {@code true} when the date is a non-holiday weekday
715	     */
716	    private boolean isBusinessDay(LocalDate date) {
717	        DayOfWeek dayOfWeek = date.getDayOfWeek();
718	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
719	            return false;
720	        }
721	        return !PUBLIC_HOLIDAYS.contains(date);
722	    }
