825	    /**
826	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
827	     * single space, upper-case the result and expand common street-type abbreviations token by token
828	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
829	     * to the empty string. The result is the canonical form that is stored, returned and used for every
830	     * address comparison (household duplicate detection and the shared household id).
831	     *
832	     * @param address the raw address, may be {@code null}
833	     * @return the normalized address
834	     */
835	    private String normalizeAddress(String address) {
836	        if (address == null) {
837	            return "";
838	        }
839	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
840	        if (collapsed.isEmpty()) {
841	            return "";
842	        }
843	        String[] tokens = collapsed.split(" ");
844	        StringBuilder sb = new StringBuilder(collapsed.length());
845	        for (int i = 0; i < tokens.length; i++) {
846	            if (i > 0) {
847	                sb.append(' ');
848	            }
849	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
850	        }
851	        return sb.toString();
852	    }
