881	        if (!EMAIL_PATTERN.matcher(email).matches()) {
882	            throw new InvalidRequestException(List.of("email"));
883	        }
884	        String lowerCased = email.toLowerCase(Locale.ROOT);
885	        // Reject an address whose domain is on the disposable-domain blocklist.
886	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
887	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
888	            throw new InvalidRequestException(List.of("email"));
