894	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
895	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
896	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
897	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
898	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
899	     * to 400 Bad Request).
900	     *
901	     * @param city     the owner's city (used to resolve the region)
902	     * @param postcode the raw postcode from the request payload, may be {@code null}
903	     */
904	    private void validatePostcode(String city, String postcode) {
905	        if (!StringUtils.hasText(postcode)) {
906	            return;
907	        }
908	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
909	            throw new InvalidRequestException(List.of("postcode"));
910	        }
911	        String region = CITY_REGION.get(city);
912	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
913	        if (range != null) {
914	            int value = Integer.parseInt(postcode);
915	            if (value < range[0] || value > range[1]) {
