921	    /**
922	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
923	     * already carries a leading '+' keeps its country code; otherwise the default country code
924	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
925	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
926	     * is thrown (mapped to 400 Bad Request).
927	     *
928	     * @param telephone the raw telephone from the request payload
929	     * @return the E.164 string (e.g. {@code +61412345678})
930	     */
931	    private String normalizeTelephone(String telephone) {
932	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
933	        String candidate;
934	        if (cleaned.startsWith("+")) {
935	            candidate = cleaned;
936	        } else {
937	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
938	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
939	        }
940	        if (!E164_PATTERN.matcher(candidate).matches()) {
941	            throw new InvalidRequestException(List.of("telephone"));
942	        }
943	        // For country codes with a known fixed national-number length, reject a candidate whose
944	        // national digits (everything after the '+' and the country code) do not match that length.
945	        String digits = candidate.substring(1);
946	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
947	            String countryCode = entry.getKey();
948	            if (digits.startsWith(countryCode)) {
949	                int nationalLength = digits.length() - countryCode.length();
950	                if (nationalLength != entry.getValue()) {
951	                    throw new InvalidRequestException(List.of("telephone"));
952	                }
953	                break;
954	            }
955	        }
956	        return candidate;
957	    }
