262	    /**
263	     * The fixed version tag mixed into the derived identifiers (member id, household id and identity
264	     * key) by the version-2 identity algorithm. Prefixing it into every hashed input guarantees each
265	     * version-2 identifier differs from the value the version-1 algorithm produced for the same owner,
266	     * so no version-1 value is ever produced again. The tag is confined to the identifiers: it never
267	     * leaks into the user-facing region ({@code locality}, {@code timezone} or the owner segment).
268	     */
269	    public static final String IDENTITY_VERSION_TAG = "V2";
270	
271	    /**
272	     * The owner's version-2 derived identity key: the single value all duplicate detection is
273	     * expressed through. It is the lower-case hex SHA-256 digest of
274	     * {@code 'V2' + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} computed
275	     * from the already-normalized stored fields, with the fixed {@code V2} version tag mixed in so it
276	     * differs from the version-1 key. Two owners are duplicates only when their whole identity keys
277	     * are equal; in particular two owners with the same last name (hence the same soundex) and
278	     * postcode but different telephones have different identity keys, so they are a soft match rather
279	     * than a hard duplicate. Not persisted: it is derived on demand from the identity-bearing fields.
280	     */
281	    @Transient
282	    public String getIdentityKey() {
283	        String telephonePart = this.telephone == null ? "" : this.telephone;
284	        String emailPart = this.email == null ? "" : this.email;
285	        String soundexPart = soundex(getLastName());
286	        return sha256Hex(IDENTITY_VERSION_TAG + "|" + telephonePart + "|" + emailPart + "|" + soundexPart);
287	    }
288	
289	    /**
290	     * Return the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code input}.
291	     *
292	     * @param input the value to digest
293	     * @return the 64-character lower-case hex digest
294	     */
295	    private static String sha256Hex(String input) {
296	        try {
297	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
298	            StringBuilder sb = new StringBuilder(digest.length * 2);
299	            for (byte b : digest) {
300	                sb.append(String.format("%02x", b));
301	            }
302	            return sb.toString();
303	        } catch (NoSuchAlgorithmException e) {
304	            throw new IllegalStateException("SHA-256 not available", e);
305	        }
306	    }
307	
308	    /**
309	     * Compute the American Soundex code of a name: the retained first letter followed by three
310	     * digits encoding the remaining consonants (padded with zeros / truncated to four characters).
311	     * The vowels {@code A E I O U Y} act as separators, {@code H} and {@code W} are transparent, and
312	     * runs of the same code collapse to a single digit. A {@code null}/letter-less value yields the
313	     * empty string. Case- and punctuation-insensitive, so two spellings of the same surname share a
314	     * code.
315	     *
316	     * @param value the name to encode, may be {@code null}
317	     * @return the four-character Soundex code, or the empty string when there are no letters
318	     */
319	    public static String soundex(String value) {
320	        if (value == null) {
321	            return "";
322	        }
323	        StringBuilder letters = new StringBuilder();
324	        for (int i = 0; i < value.length(); i++) {
325	            char c = value.charAt(i);
326	            if (Character.isLetter(c)) {
327	                letters.append(Character.toUpperCase(c));
328	            }
329	        }
330	        if (letters.length() == 0) {
331	            return "";
332	        }
333	        StringBuilder code = new StringBuilder();
334	        code.append(letters.charAt(0));
335	        char prev = soundexDigit(letters.charAt(0));
336	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
337	            char c = letters.charAt(i);
338	            if (c == 'H' || c == 'W') {
339	                // Transparent: keep the previous code so consonants either side stay adjacent.
340	                continue;
341	            }
342	            char digit = soundexDigit(c);
343	            if (digit != '0' && digit != prev) {
344	                code.append(digit);
345	            }
346	            prev = digit;
347	        }
348	        while (code.length() < 4) {
349	            code.append('0');
350	        }
351	        return code.substring(0, 4);
352	    }
353	
354	    /**
355	     * Map a single upper-case letter to its Soundex digit; {@code '0'} for the vowels {@code A E I
356	     * O U Y} and the transparent letters {@code H W}.
357	     */
358	    private static char soundexDigit(char c) {
359	        switch (c) {
360	            case 'B': case 'F': case 'P': case 'V':
361	                return '1';
362	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
363	                return '2';
364	            case 'D': case 'T':
365	                return '3';
366	            case 'L':
367	                return '4';
368	            case 'M': case 'N':
369	                return '5';
370	            case 'R':
371	                return '6';
372	            default:
373	                return '0';
374	        }
375	    }
