56	    /** The owner identity response contract version; surfaced as the top-level {@code apiVersion}. */
57	    Integer API_VERSION = 2;
58	
59	    /** City -> canonical region for the fixed city-to-region table (cities not listed have no region). */
60	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
61	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
62	
63	    /** Region -> its inclusive 4-digit postcode range {low, high}. */
64	    java.util.Map<String, int[]> REGION_POSTCODE_RANGE = java.util.Map.of(
65	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
66	
67	    /** A well-formed postcode: exactly four digits. */
68	    java.util.regex.Pattern POSTCODE_PATTERN = java.util.regex.Pattern.compile("^[0-9]{4}$");
69	
70	    /**
71	     * Group the owner's version-2 identifiers under the nested {@code identity} object: the version-2
72	     * member id, household id and identity key (each derived with the fixed {@code V2} version tag
73	     * mixed in). These identifiers no longer appear at the top level of the owner response.
74	     */
75	    default OwnerIdentityDto deriveIdentity(Owner owner) {
76	        OwnerIdentityDto identity = new OwnerIdentityDto();
77	        identity.setMemberId(owner.getMemberId());
78	        identity.setHouseholdId(owner.getHouseholdId());
79	        identity.setIdentityKey(owner.getIdentityKey());
80	        return identity;
81	    }
82	
83	    /**
84	     * Derive the owner's user-facing locality: the plain canonical region derived directly from the
85	     * owner's identity fields — the structured postcode's region range first (NSW 2000-2099,
86	     * VIC 3000-3099, QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
87	     * Brisbane->QLD), otherwise "UNKNOWN". This is the same canonical region the version-2 identifiers
88	     * are built from, but WITHOUT the {@code V2} version tag: the tag stays confined to the
89	     * identifiers, so the locality remains the plain region code (e.g. "NSW").
90	     */
91	    default String deriveLocality(Owner owner) {
92	        String postcode = owner.getPostcode();
93	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
94	            int value = Integer.parseInt(postcode);
95	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
